mapper.sql:
WHERE r.REM_ACCT_NO IN ()

    AND r.CREATED_DT >= #{f.dateFrom}


    AND r.CREATED_DT < #{f.dateTo} + 1


    AND r.MENU_CD = #{f.menuCd}


    AND r.STATUS_GROUP = #{f.statusGroup}


    AND r.REM_ACCT_NO = #{f.sourceAccountNo}


    AND UPPER(r.BEN_ACCT_NM) LIKE '%' || UPPER(#{f.beneficiaryName}) || '%'


    AND r.TRX_AMT >= #{f.amountFrom}


    AND r.TRX_AMT <= #{f.amountTo}


    AND r.REF_NO = #{f.refNo}
